        type_value = inventory['type']
        if not isinstance(type_value, str):
            self.error('E038a')
        elif not extract_spec_version:
            # When not extracting spec version, just check it's a valid type
            if not re.match(r'^https://ocfl\.io/\d+\.\d+/spec/#inventory$', type_value):
                self.error('E038a')

