            self.all_versions = all_versions

            # Validate manifest first to get unnormalized digests
            unnormalized_digests = set()
            manifest_files = {}
            if 'manifest' in inventory:
                (manifest_files, _, unnormalized_digests) = self.validate_manifest(inventory['manifest'])
                self.manifest_files = manifest_files

            # Validate versions
            self.validate_versions(versions, all_versions, unnormalized_digests)

            # Check content paths map to versions
            if manifest_files:
                self.check_content_paths_map_to_versions(manifest_files, all_versions)

    # Validate manifest
    if 'manifest' in inventory:
        manifest = inventory['manifest']
        if not isinstance(manifest, dict):
            self.error('E041a')
        else:
            (manifest_files, digests_used, unnormalized_digests) = self.validate_manifest(manifest)
            self.manifest_files = manifest_files
