def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

The input variable prior is also expected to be an InventoryValidator object
and both self and prior inventories are assumed to have been checked for
internal consistency.
    """
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior has fewer versions than self and is a prefix
    if len(prior.all_versions) >= len(self.all_versions):
        self.error('E066a', prior_versions=prior.all_versions,
                   versions=self.all_versions)
        return
    for i, version in enumerate(prior.all_versions):
        if version != self.all_versions[i]:
            self.error('E066a', prior_versions=prior.all_versions,
                       versions=self.all_versions)
            return

    # Compare states for each version in prior
    for version in prior.all_versions:
        self.compare_states_for_version(prior, version)

    # Compare manifest content paths for each version in prior
    prior_manifest = prior.inventory['manifest']
    self_manifest = self.inventory['manifest']
    for version in prior.all_versions:
        prior_state = prior.inventory['versions'][version]['state']
        self_state = self.inventory['versions'][version]['state']
        # Build logical path -> content path mapping for prior
        prior_paths = {}
        for digest, files in prior_state.items():
            for filepath in files:
                for content_path in prior_manifest.get(digest, []):
                    prior_paths[filepath] = content_path
        # Build logical path -> content path mapping for self
        self_paths = {}
        for digest, files in self_state.items():
            for filepath in files:
                for content_path in self_manifest.get(digest, []):
                    self_paths[filepath] = content_path
        # Compare content paths for matching logical files
        for filepath, prior_content_path in prior_paths.items():
            if filepath in self_paths and prior_content_path != self_paths[filepath]:
                self.error('E066c', version=version, filepath=filepath,
                           prior_content_path=prior_content_path,
                           content_path=self_paths[filepath])

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

Check the structure of the fixity block and makes sure that only files
listed in the manifest are referenced.
    """
    from .digest import digest_regex as _dr
    from digest import digest_regex, normalized_digest
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        self.error('E056a')
        return
    for algorithm in fixity:
        # Check algorithm name is valid (unless lax_digests)
        if not self.lax_digests:
            try:
                re.match(digest_regex(algorithm), '')
            except Exception:
                self.error('E056b', algorithm=algorithm)
                continue
        if not isinstance(fixity[algorithm], dict):
            self.error('E057a', algorithm=algorithm)
            continue
        seen_digests = set()
        for digest in fixity[algorithm]:
            # Check digest format
            if not self.lax_digests:
                m = re.match(digest_regex(algorithm), digest)
                if not m:
                    self.error('E057b', algorithm=algorithm, digest=digest)
                    continue
            # Check value is a list
            if not isinstance(fixity[algorithm][digest], list):
                self.error('E057c', algorithm=algorithm, digest=digest)
                continue
            # Check for duplicate normalized digests
            try:
                norm = normalized_digest(digest, algorithm)
            except Exception:
                norm = digest
            if norm in seen_digests:
                self.error('E097', algorithm=algorithm, digest=digest)
            else:
                seen_digests.add(norm)
            # Check each file is in manifest
            for file in fixity[algorithm][digest]:
                if manifest_files is not None and file not in manifest_files:
                    self.error('E057d', algorithm=algorithm, digest=digest, file=file)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

Also keep a record of any content digests different from those in the root inventory
so that we can also check them when validating the content.

version_dirs is an array of version directory names and is assumed to be in
version sequence (1, 2, 3...).
    """
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}
    prior_fixity_digests = {}

    for version_dir in version_dirs:
        inv_file = version_dir + '/inventory.json'

        # Check if version inventory exists
        if not self.obj_fs.exists(inv_file):
            self.log.error('E043', version=version_dir)
            continue

        # Validate the version inventory
        try:
            inventory, inv_validator = self.validate_inventory(
                inv_file, 
                where=version_dir,
                extract_spec_version=False
            )
        except ValidatorAbortException:
            continue

        # Check that the version inventory's version matches the directory
        if inv_validator.head != version_dir:
            self.log.error('E045', version=version_dir, head=inv_validator.head)

        # Check that the version inventory's id matches the root inventory's id
        if inv_validator.id != self.id:
            self.log.error('E046', version=version_dir, id=inv_validator.id, expected=self.id)

        # Check that the version inventory's digest algorithm matches
        if inv_validator.digest_algorithm != self.digest_algorithm:
            self.log.error('E047', version=version_dir, 
                          algorithm=inv_validator.digest_algorithm, 
                          expected=self.digest_algorithm)

        # Check that the version inventory's content directory matches
        if inv_validator.content_directory != self.content_directory:
            self.log.error('E049', version=version_dir,
                          content_directory=inv_validator.content_directory,
                          expected=self.content_directory)

        # Validate the inventory digest for this version
        self.validate_inventory_digest(inv_file, self.digest_algorithm, where=version_dir)

        # Track digests from this version's manifest
        # Structure: {digest: {path: [versions]}}
        if hasattr(inv_validator, 'manifest') and inv_validator.manifest:
            for digest, paths in inv_validator.manifest.items():
                if digest not in prior_manifest_digests:
                    prior_manifest_digests[digest] = {}
                for path in paths:
                    if path not in prior_manifest_digests[digest]:
                        prior_manifest_digests[digest][path] = []
                    if version_dir not in prior_manifest_digests[digest][path]:
                        prior_manifest_digests[digest][path].append(version_dir)

        # Track digests from this version's fixity
        # Structure: {algorithm: {digest: {path: [versions]}}}
        if hasattr(inv_validator, 'fixity') and inv_validator.fixity:
            for algorithm, digests in inv_validator.fixity.items():
                if algorithm not in prior_fixity_digests:
                    prior_fixity_digests[algorithm] = {}
                for digest, paths in digests.items():
                    if digest not in prior_fixity_digests[algorithm]:
                        prior_fixity_digests[algorithm][digest] = {}
                    for path in paths:
                        if path not in prior_fixity_digests[algorithm][digest]:
                            prior_fixity_digests[algorithm][digest][path] = []
                        if version_dir not in prior_fixity_digests[algorithm][digest][path]:
                            prior_fixity_digests[algorithm][digest][path].append(version_dir)

    return (prior_manifest_digests, prior_fixity_digests)

