def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

*level* sets the maximum depth of recursion. For infinite recursion,
set that to -1. For level 1,
if a key is present both in *d1* and *d2* but has different values,
it is included into the difference.
See :func:`intersection` for more details.

*d1* and *d2* remain unchanged. However, *d1* or some of its
subdictionaries may be returned directly.
Make a deep copy of the result when appropriate.

.. versionadded:: 0.5
   add keyword argument *level*.
    """
    import copy
    import lena.core
    import copy
    import lena.core
    import copy
    import lena.core
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        return d1
    if not isinstance(d2, dict):
        return d1

    if level == 0:
        if d1 == d2:
            return {}
        return d1

    result = {}
    for key, val in d1.items():
        if key not in d2:
            result[key] = val
            continue
        val2 = d2[key]
        if isinstance(val, dict) and isinstance(val2, dict):
            if level == 1:
                if val != val2:
                    result[key] = val
            else:
                next_level = level - 1 if level > 0 else -1
                sub_diff = difference(val, val2, level=next_level)
                if sub_diff:
                    result[key] = sub_diff
        else:
            if val != val2:
                result[key] = val
    return result

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
Sequence is derived from *seq*
(or is *seq*, if that is of a sequence type).
    """
    from . import fill_compute_seq
    from . import fill_request_seq
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if ct.is_source(seq):
        return (seq, "source")

    if isinstance(seq, fill_request_seq.FillRequestSeq):
        return (seq, "fill_request")

    if isinstance(seq, fill_compute_seq.FillComputeSeq):
        return (seq, "fill_compute")

    if ct.is_fill_request_seq(seq):
        seq = fill_request_seq.FillRequestSeq(seq, bufsize=bufsize)
        return (seq, "fill_request")

    if ct.is_fill_compute_seq(seq):
        seq = fill_compute_seq.FillComputeSeq(seq, bufsize=bufsize)
        return (seq, "fill_compute")

    raise exceptions.LenaTypeError(
        "unknown argument type. Must be one of "
        "FillComputeSeq, FillRequestSeq or Source, "
        "{} provided".format(seq)
    )

def render(pieces, style):
    """
    Render the given version pieces into the requested style.
    """
    """
    Render the given version pieces into the requested style.
    """
    if pieces["error"]:
        return {
            "version": "unknown",
            "full-revisionid": pieces.get("long"),
            "dirty": None,
            "error": pieces["error"],
            "date": None,
        }

    if not style or style == "default":
        style = "pep440"  # the default

    if style == "pep440":
        rendered = render_pep440(pieces)
    elif style == "pep440-pre":
        rendered = render_pep440_pre(pieces)
    elif style == "pep440-post":
        rendered = render_pep440_post(pieces)
    elif style == "pep440-old":
        rendered = render_pep440_old(pieces)
    elif style == "git-describe":
        rendered = render_git_describe(pieces)
    else:
        raise ValueError("unknown style '%s'" % style)

    return {
        "version": rendered,
        "full-revisionid": pieces["long"],
        "dirty": pieces["dirty"],
        "error": None,
        "date": pieces.get("date"),
    }

def get_versions():
    """
    Get version information or return default if unable to do so.
    """
    """
    Get version information or return default if unable to do so.
    """
    # I am in _version.py, which lives at ROOT/VERSIONFILE_SOURCE. If we have
    # __file__, we can work backwards from there to the root. Some
    # py2exe/bbfreeze/non-CPython implementations don't do __file__, in which
    # case we can only use expanded keywords.

    cfg = get_config()
    verbose = cfg.verbose

    try:
        return git_versions_from_keywords(get_keywords(), cfg.tag_prefix, verbose)
    except NotThisMethod:
        pass

    try:
        root = os.path.realpath(__file__)
        # versionfile_source is the relative path from the top of the source
        # tree (where the .git directory might live) to this file. Invert
        # this to find the root from __file__.
        for _ in cfg.versionfile_source.split('/'):
            root = os.path.dirname(root)
    except NameError:
        return {
            "version": "0+unknown",
            "full-revisionid": None,
            "dirty": None,
            "error": "unable to find root of source tree",
            "date": None,
        }

    try:
        pieces = git_pieces_from_vcs(cfg.tag_prefix, root, verbose)
        return render(pieces, cfg.style)
    except NotThisMethod:
        pass

    try:
        if cfg.parentdir_prefix:
            return versions_from_parentdir(cfg.parentdir_prefix, root, verbose)
    except NotThisMethod:
        pass

    return {
        "version": "0+unknown",
        "full-revisionid": None,
        "dirty": None,
        "error": "unable to compute version",
        "date": None,
    }

