def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    default = {"hcard_url": None}

    if not document:
        return default

    # Try JSON first (new format)
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            links = data.get("links", [])
            for link in links:
                if link.get("rel") == "http://microformats.org/profile/hcard":
                    return {"hcard_url": link.get("href")}
        return default
    except (json.JSONDecodeError, ValueError, TypeError):
        pass

    # Try XRD/XML format (old format)
    try:
        xrd = XRD.parse_xrd(document)
        link = xrd.find_link(rels="http://microformats.org/profile/hcard")
        if link:
            return {"hcard_url": link.href}
        return default
    except Exception:
        pass

    return default

